  Map<String, dynamic> customJson(String id, String data) => {
    'type': 'custom',
    'id': id,
    'parentId': null,
    'timestamp': '2026-01-01T00:00:00.000Z',
    'customType': 'note',
    'data': data,
  };

  Map<String, dynamic> toolResultJson(String id, int payloadBytes) => {
    'type': 'message',
    'id': id,
    'parentId': null,
