      expect(r.parseCacheHitCount, greaterThan(0));
      expect(idsOf(second), idsOf(first));
      expect([
        for (final entry in second.entries) entry.record.toJson(),
      ], equals([for (final entry in first.entries) entry.record.toJson()]));
    });

