    final lines = full.split('\n')..removeLast();
    final shrunk = '${lines.take(3).join('\n')}\n';
    final write = await fs.writeFile(path, shrunk);
    write.getOrThrow();

    final after = await r.readTail();
    expect(idsOf(after), ['u0', 'u1']);
