    // signal (the rule `ingestAppended` uses for same-size rewrites).
    final content = (await fs.readTextFile(path)).getOrThrow();
    final rewritten = content.replaceFirst('"msg 0"', '"msg 9"');
    expect(rewritten.length, content.length);
