    result.getOrThrow();
  }

  /// Byte offset of the line carrying [id] in the just-written file.
  Future<int> offsetOfId(String id) async {
    final content = (await fs.readTextFile(path)).getOrThrow();
    var offset = 0;
    for (final line in content.split('\n')) {
